            double Ey_0_0_0 = exp(((zeta * PA_y) * PB_y));
            double Ez_0_0_0 = exp(((zeta * PA_z) * PB_z));
            E[0][0] = ((Ex_0_0_0 * Ey_0_0_0) * Ez_0_0_0);
